"""
SQLAlchemy ORM models for CyberSentinel threat detection, alerts, and agent orchestration.
"""
from datetime import datetime
from sqlalchemy import Column, Integer, String, Float, DateTime, Text, Boolean, JSON
from src.core.database import Base


class Alert(Base):
    """Network flow alert generated by detection agents or ML inference."""
    __tablename__ = "alerts"

    id = Column(Integer, primary_key=True, index=True)
    created_at = Column(DateTime, default=datetime.utcnow, index=True)
    source_ip = Column(String(45), nullable=True)  # Stored for triage/audit, NOT model feature
    destination_ip = Column(String(45), nullable=True)
    source_port = Column(Integer, nullable=True)
    destination_port = Column(Integer, nullable=True)
    protocol = Column(String(10), nullable=True)
    
    detection_label = Column(String(100), nullable=False, index=True)  # BENIGN or Attack Type
    is_attack = Column(Boolean, default=False, index=True)
    confidence = Column(Float, nullable=False)
    model_name = Column(String(100), nullable=False)
    
    # Explainability & Telemetry
    top_features = Column(JSON, nullable=True)  # SHAP top contributors
    raw_flow_data = Column(JSON, nullable=True)
    status = Column(String(50), default="NEW")  # NEW, TRIAGED, INVESTIGATING, CLOSED


class Investigation(Base):
    """Threat investigation case opened by the autonomous agent team."""
    __tablename__ = "investigations"

    id = Column(Integer, primary_key=True, index=True)
    title = Column(String(255), nullable=False)
    created_at = Column(DateTime, default=datetime.utcnow, index=True)
    updated_at = Column(DateTime, default=datetime.utcnow, onupdate=datetime.utcnow)
    severity = Column(String(20), default="MEDIUM")  # LOW, MEDIUM, HIGH, CRITICAL
    status = Column(String(50), default="ACTIVE")  # ACTIVE, RESOLVED, DISMISSED
    summary = Column(Text, nullable=True)
    root_cause = Column(Text, nullable=True)
    recommended_mitigation = Column(Text, nullable=True)


class AgentAuditLog(Base):
    """Immutable audit trail of autonomous multi-agent deliberations and actions."""
    __tablename__ = "agent_audit_logs"

    id = Column(Integer, primary_key=True, index=True)
    timestamp = Column(DateTime, default=datetime.utcnow, index=True)
    agent_name = Column(String(100), nullable=False, index=True)
    action_type = Column(String(100), nullable=False)
    target_id = Column(String(100), nullable=True)
    details = Column(JSON, nullable=True)
    reasoning = Column(Text, nullable=True)


class DatasetRegistry(Base):
    """Metadata and lineage tracking for ingested datasets and samples."""
    __tablename__ = "dataset_registry"

    id = Column(Integer, primary_key=True, index=True)
    dataset_name = Column(String(100), nullable=False)
    source_path = Column(String(500), nullable=False)
    total_records = Column(Integer, nullable=False)
    benign_count = Column(Integer, nullable=False)
    attack_count = Column(Integer, nullable=False)
    processed_at = Column(DateTime, default=datetime.utcnow)
    file_hash_sha256 = Column(String(64), nullable=True)
    metadata_json = Column(JSON, nullable=True)


class AnalysisJob(Base):
    """Execution record for an end-to-end multi-agent threat analysis."""
    __tablename__ = "analysis_jobs"

    id = Column(String(100), primary_key=True, index=True)
    created_at = Column(DateTime, default=datetime.utcnow, index=True)
    completed_at = Column(DateTime, nullable=True)
    status = Column(String(50), default="QUEUED", index=True)  # QUEUED, PROCESSING, COMPLETED, FAILED
    filename = Column(String(255), nullable=True)
    total_flows = Column(Integer, default=0)
    attacks_detected = Column(Integer, default=0)
    anomalies_detected = Column(Integer, default=0)
    correlated_incidents_count = Column(Integer, default=0)
    risk_score = Column(Float, nullable=True)
    severity = Column(String(20), nullable=True)
    executive_summary = Column(Text, nullable=True)
    results_json = Column(JSON, nullable=True)
    error_message = Column(Text, nullable=True)


